select sp.project_type_id, sp.project_type_name, spa.param_name, ddt.param_id, if(dpc.id is null,1,0) as ifConfig,
if(dpc.id is null,IFNULL(sum(case when sp.id in (${projectIds}) then ddt.param_value else 0 end ),0),dpc.param_value) as totalValue
0 as totalValue
from data_device_real_time ddt left join sys_device sd on ddt.device_id = sd.id left join sys_project sp on sp.id = sd.project_id left join sys_param spa on spa.id = ddt.param_id left join data_param_config dpc on dpc.project_id = sp.id and dpc.del_flag = 0 and dpc.if_enable = 1 and dpc.data_type = 1 and dpc.param_id = spa.id where ddt.del_flag = 0 and sd.del_flag = 0 and sp.del_flag = 0 and spa.del_flag = 0
and sp.province_code = #{provinceCode}
and sp.project_type_id = #{projectTypeId}
and ddt.param_id = #{paramId}
and ddt.param_id in
#{item}
and sp.project_type_id in
#{item}
and if(sp.project_type_id = 2 and ddt.param_id in (110004,110003,110041,100001),ddt.device_id = 12,true) group by ddt.param_id,sp.project_type_id
